const PROFILES={low:[.08,.08,.08,.08],medium:[.20,.20,.20,.20],heavy:[.34,.34,.34,.34],unbalanced:[.36,.36,.09,.09]};
const state={scenario:'medium',controller:'dqn',speed:5,running:true,t:0,queues:[0,0,0,0],phase:0,phaseAge:0,yellow:0,pending:null,arrived:0,processed:0,delay:0,switches:0,history:[],events:[],fixedAge:0,lastQueue:0};
const $=id=>document.getElementById(id);const dirs=['north','south','east','west'];
function poisson(lambda){let L=Math.exp(-lambda),p=1,k=0;do{k++;p*=Math.random()}while(p>L);return k-1}
function rates(){if(state.scenario!=='rush')return PROFILES[state.scenario];const p=(state.t%1200)/1200;if(p<.25)return PROFILES.low;if(p<7/12)return [.38,.38,.10,.10];if(p<5/6)return [.10,.10,.38,.38];return PROFILES.medium}
function chooseAction(){const ns=state.queues[0]+state.queues[1],ew=state.queues[2]+state.queues[3];if(state.yellow)return 0;if(state.controller==='random')return Math.floor(Math.random()*3);if(state.controller==='fixed'){state.fixedAge++;if(state.fixedAge>=30){state.fixedAge=0;return state.phase===0?2:1}return 0}if(state.phaseAge<5)return 0;if(state.controller==='heuristic'){const current=state.phase===0?ns:ew,opp=state.phase===0?ew:ns;return opp>current*1.2&&opp>0?(state.phase===0?2:1):0}const imbalance=state.phase===0?ew-ns:ns-ew;const oldestPressure=Math.max(...state.queues);if(imbalance>Math.max(3,(state.phase===0?ns:ew)*.16)||state.phaseAge>55||oldestPressure>34)return state.phase===0?2:1;return 0}
function log(message){state.events.unshift({t:state.t,message});state.events=state.events.slice(0,4)}
function step(){const action=chooseAction();if(!state.yellow&&action&&action-1!==state.phase&&state.phaseAge>=5){state.pending=action-1;state.yellow=3;state.switches++;log(`Phase change requested · ${state.pending===0?'NS':'EW'} next`)}const incoming=rates().map(poisson);incoming.forEach((v,i)=>{state.arrived+=v;state.queues[i]=Math.min(100,state.queues[i]+v)});state.delay+=state.queues.reduce((a,b)=>a+b,0);if(state.yellow){state.yellow--;if(state.yellow===0){state.phase=state.pending;state.pending=null;state.phaseAge=0;log(`${state.phase===0?'North–south':'East–west'} green active`)}}else{const active=state.phase===0?[0,1]:[2,3];active.forEach(i=>{if(state.queues[i]&&Math.random()<.8){state.queues[i]--;state.processed++}});state.phaseAge++}state.t++;state.history.push([state.queues[0]+state.queues[1],state.queues[2]+state.queues[3]]);if(state.history.length>120)state.history.shift();if(state.t%60===0)log(`Minute ${Math.floor(state.t/60)} · ${state.processed} vehicles cleared`);if(state.t>=1200)reset(false)}
function reset(announce=true){Object.assign(state,{t:0,queues:[0,0,0,0],phase:0,phaseAge:0,yellow:0,pending:null,arrived:0,processed:0,delay:0,switches:0,history:[],events:[],fixedAge:0,lastQueue:0});if(announce)log('Simulation reset · new arrival stream');render()}
function cars(el,count){const shown=Math.min(count,12);el.innerHTML=Array.from({length:shown},(_,i)=>`<span class="car ${i<2?'hot':''}"></span>`).join('')}
function formatTime(s){return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
function drawChart(){const canvas=$('queueChart'),ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height,pad=18;ctx.clearRect(0,0,w,h);ctx.strokeStyle='#232c35';ctx.lineWidth=1;for(let i=0;i<4;i++){const y=pad+(h-pad*2)*i/3;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(w-pad,y);ctx.stroke()}const max=Math.max(12,...state.history.flat());[['#26e6a4',0],['#43c6e8',1]].forEach(([color,index])=>{ctx.strokeStyle=color;ctx.lineWidth=3;ctx.beginPath();state.history.forEach((v,i)=>{const x=pad+(w-pad*2)*i/119,y=h-pad-v[index]/max*(h-pad*2);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke()})}
function render(){const total=state.queues.reduce((a,b)=>a+b,0),avg=state.arrived?state.delay/state.arrived:0,completion=state.arrived?state.processed/state.arrived*100:0,ns=state.queues[0]+state.queues[1],ew=state.queues[2]+state.queues[3],max=Math.max(ns,ew,1);$('totalQueue').textContent=total;$('avgWait').textContent=avg.toFixed(1);$('throughput').textContent=state.processed;$('completion').textContent=completion.toFixed(1);$('switchCount').textContent=state.switches;$('arrivalCount').textContent=`${state.arrived} arrivals`;$('simTime').textContent=formatTime(state.t);dirs.forEach((d,i)=>{$(`${d}Queue`).textContent=state.queues[i];cars(document.querySelector(`.queue-${d[0]}`),state.queues[i])});const inter=$('intersection');inter.className=`intersection ${state.yellow?'yellow':state.phase===0?'ns-green':'ew-green'}`;const phase=state.yellow?'YELLOW':state.phase===0?'NS GREEN':'EW GREEN';$('phaseBadge').querySelector('b').textContent=phase;$('phaseTimer').textContent=`${state.yellow?state.yellow:state.phaseAge}s`;$('phaseBadge').querySelector('span').style.background=state.yellow?'var(--amber)':'var(--green)';$('nsDemand').textContent=ns;$('ewDemand').textContent=ew;$('nsDemandBar').style.width=`${ns/max*100}%`;$('ewDemandBar').style.width=`${ew/max*100}%`;const hold=state.yellow?'Safety transition':state.phase===0?'Hold north–south':'Hold east–west';$('decisionTitle').textContent=hold;const conf=Math.min(96,Math.round(70+Math.abs(ns-ew)/(total||1)*25));$('confidence').textContent=`${conf}%`;$('decisionCopy').textContent=state.yellow?'All approaches stopped while the next green phase is armed.':`${state.controller==='dqn'?'Demo policy':'Controller'} is balancing queue pressure with minimum green time.`;const delta=state.lastQueue?((total-state.lastQueue)/state.lastQueue*100):0;$('queueTrend').textContent=`${delta<=0?'↓':'↑'} ${Math.abs(delta).toFixed(1)}%`;$('queueTrend').style.color=delta<=0?'var(--green)':'var(--red)';state.lastQueue=total;$('eventLog').innerHTML=state.events.length?state.events.map(e=>`<li><time>${formatTime(e.t)}</time><strong>${e.message}</strong></li>`).join(''):'<li><time>00:00</time><strong>Monitoring stochastic arrivals</strong></li>';drawChart()}
setInterval(()=>{$('clock').textContent=new Date().toLocaleTimeString('en-GB')},1000);setInterval(()=>{if(state.running){for(let i=0;i<state.speed;i++)step();render()}},500);
$('scenarioButtons').addEventListener('click',e=>{if(!e.target.dataset.scenario)return;document.querySelectorAll('[data-scenario]').forEach(b=>b.classList.remove('active'));e.target.classList.add('active');state.scenario=e.target.dataset.scenario;reset();log(`Traffic profile · ${e.target.textContent}`);render()});$('controllerSelect').addEventListener('change',e=>{state.controller=e.target.value;state.fixedAge=0;log(`Controller changed · ${e.target.options[e.target.selectedIndex].text}`);render()});$('speedSelect').addEventListener('change',e=>state.speed=Number(e.target.value));$('playButton').addEventListener('click',()=>{state.running=!state.running;$('playButton').querySelector('span:last-child').textContent=state.running?'Pause run':'Resume run';$('playButton').querySelector('.pause-icon').textContent=state.running?'Ⅱ':'▶';$('runStatus').textContent=state.running?'SIMULATION LIVE':'SIMULATION PAUSED';document.querySelector('.pulse').style.background=state.running?'var(--green)':'var(--amber)'});$('resetButton').addEventListener('click',()=>reset());
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;context.registerTool({name:'configure_traffic_simulation',title:'Configure traffic simulation',description:'Set the visible traffic profile, controller, and simulation speed, then reset the run.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:['low','medium','heavy','unbalanced','rush']},controller:{type:'string',enum:['dqn','heuristic','fixed','random']},speed:{type:'number',enum:[1,2,5,10]}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(input.scenario){const button=document.querySelector(`[data-scenario="${input.scenario}"]`);button?.click()}if(input.controller){$('controllerSelect').value=input.controller;$('controllerSelect').dispatchEvent(new Event('change'))}if(input.speed){$('speedSelect').value=String(input.speed);state.speed=input.speed}reset();return{scenario:state.scenario,controller:state.controller,speed:state.speed,status:'configured'}}});context.registerTool({name:'read_traffic_metrics',title:'Read traffic metrics',description:'Read current queues, throughput, delay, signal phase, and simulation time.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{timestep:state.t,queues:{north:state.queues[0],south:state.queues[1],east:state.queues[2],west:state.queues[3]},phase:state.yellow?'yellow':state.phase===0?'ns_green':'ew_green',arrived:state.arrived,processed:state.processed,average_wait:state.arrived?Number((state.delay/state.arrived).toFixed(2)):0,switches:state.switches}}})}
reset(false);log('Medium traffic · DQN demo policy active');render();registerTools();
